#!/usr/bin/env python3
"""Adds Petmate's iOS settings to the files generated by `flutter create`.

Why a script instead of a committed Info.plist: since Flutter 3.38 the iOS
template uses the UIScene lifecycle (Info.plist `UIApplicationSceneManifest`
+ SceneDelegate.swift + `FlutterImplicitEngineDelegate` in AppDelegate),
older templates do not. A hand-written Info.plist breaks one or the other, so
we let `flutter create` generate the right one for the installed Flutter and
only merge our keys into it. Idempotent; standard library only (macOS python3).

Usage (from app/):
    flutter create . --org com.oversonic --project-name petmate --platforms android,ios
    flutter build ios --config-only --no-codesign   # generates ios/Podfile
    python3 tools/patch_ios.py
"""
from __future__ import annotations

import plistlib
import re
import sys
from pathlib import Path

APP = Path(__file__).resolve().parent.parent
INFO = APP / "ios" / "Runner" / "Info.plist"
PODFILE = APP / "ios" / "Podfile"

INFO_KEYS = {
    "CFBundleDisplayName": "Petmate",
    # MVP: the cloud runs on the developer laptop over plain HTTP/WS.
    # NSAllowsArbitraryLoads is for development only — remove before release.
    "NSAppTransportSecurity": {
        "NSAllowsArbitraryLoads": True,
        "NSAllowsLocalNetworking": True,
    },
    "NSBluetoothAlwaysUsageDescription":
        "Petmate usa il Bluetooth per trovare il robot e configurarne la connessione Wi-Fi.",
    "NSBluetoothPeripheralUsageDescription":
        "Petmate usa il Bluetooth per trovare il robot e configurarne la connessione Wi-Fi.",
    "NSLocalNetworkUsageDescription":
        "Petmate si collega al server e al robot sulla rete di casa per la diretta video.",
    # Not requested by the MVP (live video is receive-only), but required by
    # Apple as soon as the binary links WebRTC capture / permission_handler.
    "NSCameraUsageDescription":
        "La fotocamera serve per mostrare il tuo viso sul display del robot durante la diretta.",
    "NSMicrophoneUsageDescription":
        "Il microfono serve per parlare con il tuo animale attraverso il robot.",
}

# permission_handler compiles every permission out unless enabled here.
PERMISSION_MACROS = [
    "PERMISSION_BLUETOOTH=1",
    "PERMISSION_MICROPHONE=1",
    "PERMISSION_CAMERA=1",
    "PERMISSION_NOTIFICATIONS=1",
]
MIN_IOS = "13.0"


def patch_info() -> None:
    if not INFO.exists():
        sys.exit(f"{INFO} not found: run `flutter create . --platforms android,ios` first")
    with INFO.open("rb") as f:
        info = plistlib.load(f)
    changed = []
    for k, v in INFO_KEYS.items():
        if isinstance(v, dict):
            cur = info.get(k)
            cur = dict(cur) if isinstance(cur, dict) else {}
            merged = {**cur, **v}
            if merged != info.get(k):
                info[k] = merged
                changed.append(k)
        elif info.get(k) != v:
            info[k] = v
            changed.append(k)
    if "UIApplicationSceneManifest" in info and not (APP / "ios" / "Runner" / "SceneDelegate.swift").exists():
        print("WARNING: Info.plist declares UIApplicationSceneManifest but ios/Runner/SceneDelegate.swift "
              "is missing — re-run `flutter create` or remove the scene manifest.")
    with INFO.open("wb") as f:
        plistlib.dump(info, f, sort_keys=False)
    print(f"Info.plist: {'updated ' + ', '.join(changed) if changed else 'already up to date'}")


def patch_podfile() -> None:
    if not PODFILE.exists():
        print("ios/Podfile not found yet: run `flutter build ios --config-only --no-codesign` (or `flutter run` once), "
              "then run this script again.")
        return
    src = PODFILE.read_text()
    out = src
    # 1) platform :ios, '13.0' (uncomment / raise)
    m = re.search(r"^\s*#?\s*platform :ios, '([0-9.]+)'\s*$", out, re.M)
    if m:
        cur = tuple(int(x) for x in m.group(1).split("."))
        want = tuple(int(x) for x in MIN_IOS.split("."))
        ver = m.group(1) if cur >= want else MIN_IOS
        out = out[: m.start()] + f"platform :ios, '{ver}'" + out[m.end():]
    else:
        out = f"platform :ios, '{MIN_IOS}'\n" + out
    # 2) permission_handler macros inside post_install
    if "PERMISSION_BLUETOOTH=1" not in out:
        anchor = re.search(r"^(\s*)flutter_additional_ios_build_settings\(target\)\s*$", out, re.M)
        if anchor:
            ind = anchor.group(1)
            macros = ",\n".join(f"{ind}    '{x}'" for x in PERMISSION_MACROS)
            block = (
                f"\n{ind}target.build_configurations.each do |config|\n"
                f"{ind}  config.build_settings['GCC_PREPROCESSOR_DEFINITIONS'] ||= [\n"
                f"{ind}    '$(inherited)',\n{macros},\n"
                f"{ind}  ]\n"
                f"{ind}end"
            )
            out = out[: anchor.end()] + block + out[anchor.end():]
        else:
            print("WARNING: post_install hook not found in Podfile; add the permission_handler macros by hand "
                  "(see README).")
    if out != src:
        PODFILE.write_text(out)
        print("Podfile: updated (platform + permission_handler macros). Run `cd ios && pod install`.")
    else:
        print("Podfile: already up to date")


if __name__ == "__main__":
    patch_info()
    patch_podfile()
